			Resource:  resource,
			Operation: operation,
			From:      c.Query("from"),
			To:        c.Query("to"),
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, gin.H{"events": events})
